(() => {
 'use strict';
 const C=window.SecondLookCore, key='second-look-demo-v1';let current='TC01',records={},toastTimer;
 try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old&&old.version===1){current=old.current;records=old.records||{};}}catch{}
 if(!C.cases.some(c=>c.id===current))current='TC01';
 const getCase=()=>C.cases.find(c=>c.id===current), getState=()=>records[current]||(records[current]=C.fresh(getCase()));
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const btn=(text,action,extra='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
 function persist(){try{localStorage.setItem(key,JSON.stringify({version:1,current,records}));}catch{}}
 function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3000);}
 function event(t){getState().events.push({at:new Date().toISOString(),text:t});}
 function evidence(c,refs){return`<div class="evidence-grid">${(refs||c.evidence.map((_,i)=>i)).map(i=>`<div class="evidence"><span class="evidence-code">E${i+1}</span><span>${esc(c.evidence[i])}</span></div>`).join('')}</div>`;}
 function options(values,value){return values.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('');}
 function render(){const c=getCase(),s=getState();document.getElementById('app').innerHTML=`
 <div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">↗</div><div><strong>再遇</strong><small>SECOND LOOK</small></div></div>
 <div><div class="nav-label">RECRUITING WORKSPACE</div><nav class="side-nav"><span class="active">↗ 人才转推 <b class="count">5</b></span><span>▤ 面试评估</span><span>◫ 岗位机会</span></nav></div>
 <div class="side-note"><b>让一次面试，留下更多可能。</b>从具体能力出发，发现值得进一步了解的岗位。<p style="margin-top:18px;font-size:10px">产品概念 Demo<br>预置建议 · 模拟数据<br>不会真实发送邮件</p></div></aside>
 <main class="main"><header class="topbar"><div class="breadcrumb">招聘工作台 <b>／ 面试后人才转推</b></div><div class="top-actions"><span class="badge demo">● 交互演示 · 模拟数据</span><span class="avatar">HR</span></div></header>
 <div class="content"><div class="heading"><div><div class="eyebrow">A NEW POSSIBILITY</div><h1>让合适的人，遇见下一次机会。</h1><p>面试官留下依据，系统整理建议，每一次沟通由 HR 决定。</p></div><div class="compact-actions">${btn('导出演示记录','export','','secondary')}</div></div>
 <div class="workspace"><aside class="case-panel"><div class="case-panel-head"><b>候选人样例</b><small>5 个场景</small></div>${C.cases.map(x=>{const r=records[x.id];return`<button class="case ${current===x.id?'current':''}" data-action="case" data-id="${x.id}" aria-current="${current===x.id?'true':'false'}"><div class="case-top"><span class="initial">${esc(x.name.slice(0,1))}</span><span class="case-name">${esc(x.name)}</span><span class="case-code">${x.id}</span></div><div class="case-role">${esc(x.short)}</div><div class="case-bottom"><span class="case-sub">${x.intent==='yes'?'有转推依据':'推荐意愿未确认'}</span><span class="muted">${r?.sent?'已模拟发送':'待处理'}</span></div></button>`;}).join('')}<div class="case-note">所有人选和岗位均为虚构。切换样例可比较不同转推边界。</div></aside>
 <section class="work-area"><nav class="stepper" aria-label="工作步骤">${['面评确认','岗位复核','沟通审核','候选人视角'].map((t,i)=>`<button class="step ${s.step===i+1?'on':''} ${s.analyzed&&i<2?'done':''}" data-action="step" data-step="${i+1}" ${i>0&&!s.analyzed?'disabled':''}><span class="step-num">${i+1}</span>${t}</button>`).join('')}</nav>
 <div class="candidate-head"><div class="person"><div class="person-avatar">${esc(c.name.slice(0,1))}</div><div><h2>${esc(c.name)}<small>${c.id} · 模拟候选人</small></h2><div class="meta"><span>${esc(c.degree)}</span><span>意向 ${esc(c.city)}</span></div><div class="meta"><span>原申请：${esc(c.original)}</span></div></div></div><span class="status">${s.sent?'已完成模拟发送':s.analyzed?'等待 HR 决策':'面评待确认'}</span></div>
 ${s.step===1?interview(c,s):s.step===2?review(c,s):s.step===3?editor(c,s):candidate(c,s)}
 <div class="footer"><span>SECOND LOOK · 每一条建议，都应有依据。</span><span>预置输出，无真实模型调用 ${btn('重置当前案例','reset','','ghost')}</span></div></section></div></div></main></div>`;persist();}
 function interview(c,s){return`<div class="panel"><div class="panel-title"><h2>先确认这次面试的结论</h2><span class="eyebrow">01 / INTERVIEW</span></div><p class="subtext">推荐意愿由面试官给出，系统不会替面试官作出认可。</p><label class="label">面试官面评</label><div class="assessment">${esc(c.assessment)}</div><div class="form-grid"><div><label class="label" for="verdict">原岗位结论</label><select id="verdict" ${s.sent?'disabled':''}>${options([['不推进','本次岗位不推进'],['推进','进入原岗位下一阶段'],['待定','待补充评估']],s.verdict)}</select></div><div><label class="label" for="intent">是否值得考虑其他岗位</label><select id="intent" ${s.sent?'disabled':''}>${options([['yes','是，有具体推荐依据'],['unknown','尚未确认'],['no','本次不建议转推']],s.intent)}</select></div></div><label class="label">面试官的推荐依据</label><div class="notice">${esc(c.endorsement)}</div><label class="label">简历与面试中的材料摘要</label>${evidence(c)}${s.verdict!=='不推进'?'<div class="notice warn">原岗位仍在推进或评估中，请先完成原流程；本任务不会发送未通过通知。</div>':''}<div class="actions"><span class="progress-line">本演示使用既有案例的预置建议，不进行自由文本模型推理。</span>${btn(s.analyzed?'重新整理示例建议 →':'整理示例建议 →','analyze',s.verdict!=='不推进'||s.sent?'disabled':'')}</div></div>`;}
 function scenario(s){return`<div class="scenario"><span>◇ 场景验证</span><span>切换以检查推荐边界</span><select id="scenario" aria-label="场景验证" ${s.sent?'disabled':''}>${options([['normal','正常岗位状态'],['closed','目标岗位已关闭'],['city','目标岗位城市不符']],s.scenario)}</select></div>`;}
 function review(c,s){const jobs=C.jobs(c,s),valid=jobs.filter(j=>j.eligible);return`<div class="panel"><div class="panel-title"><h2>把机会建立在证据上</h2><span class="eyebrow">02 / MATCH REVIEW</span></div><div class="summary"><div class="summary-label">✧ 内部摘要 · 预置示例</div><p>${esc(s.intent==='yes'?c.summary:s.intent==='no'?'当前面试官不建议转推，系统保留此判断；HR 可退回核实，不能将其改写成推荐。':'面试官的转推意愿尚未确认。即使存在关键词重合，也暂不发起岗位邀请。')}</p></div>${scenario(s)}<div class="panel-title"><h3>岗位复核 <span class="muted" style="font-size:11px;font-weight:400">${valid.length} 个可进一步考虑</span></h3><label class="checkrow" style="font-size:10px;margin:0"><input id="supply" type="checkbox" ${s.supply?'checked':''} ${s.sent?'disabled':''}>参考补充人选需求</label></div>${!valid.length?`<div class="notice warn">${s.scenario==='closed'?'当前岗位均已关闭，停止岗位邀请。':s.scenario==='city'?'当前目标岗位城市不符合已知意向，停止岗位邀请。':'暂不形成岗位推荐；HR 仍可及时告知原岗位结果。'}</div>`:''}<div class="jobs">${jobs.map(j=>`<article class="job ${j.eligible&&s.selected.includes(j.id)?'selected':''} ${!j.eligible?'blocked':''}"><div class="job-top"><input class="job-check" type="checkbox" data-job="${j.id}" aria-label="选择${esc(j.name)}" ${s.selected.includes(j.id)&&j.eligible?'checked':''} ${!j.eligible||s.sent?'disabled':''}><div class="job-heading"><h3>${esc(j.name)}</h3><div class="job-meta">${j.id} · ${esc(j.city)} · ${esc(j.owner)}</div><span class="tag ${j.eligible?'':'red'}">${j.eligible?'可进一步评估':esc(j.blocked)}</span>${j.need?'<span class="tag gold">需补充合格人选 · 内部</span>':''}<p class="job-reason">${esc(j.reason)}</p><details><summary>查看岗位要求与原始依据</summary><p>${esc(j.require)}</p>${evidence(c,j.refs)}</details></div></div></article>`).join('')}</div><p class="mini-note">缺少证据不代表没有能力。岗位缺人不能覆盖关键条件，推荐也不代表已获面试或录用。</p><div class="actions">${btn('← 返回面评','step','data-step="1"','secondary')}<div class="actions-right">${btn('进入沟通审核 →','step','data-step="3"')}</div></div></div>`;}
 function emailMarkup(c,s,snapshot){const data=snapshot||{feedback:s.includeFeedback?s.feedback:null,jobs:s.includeJobs?C.chosen(c,s):[]};return`<div class="email"><div class="email-header">收件人：${esc(c.name)}（模拟，无真实地址）<strong>关于您本次应聘结果与后续机会</strong></div><div class="email-body"><div class="email-brand">再遇</div><p>${esc(c.name)}，您好：</p><p style="margin-top:12px">感谢您参与${esc(c.original)}岗位的面试。综合本次岗位要求，我们暂不推进您在该岗位的后续流程。</p>${data.feedback?`<p style="margin-top:13px">${esc(data.feedback)}</p>`:''}${data.jobs.length?`<p style="margin-top:14px">根据您已提供的经历，以下在招岗位可能值得进一步了解。如果有兴趣，您可以选择是否考虑：</p>${data.jobs.map(j=>`<div class="invite"><strong>${esc(j.name)}</strong><p>${esc(j.city)} · 2027 校招</p></div>`).join('')}<p class="muted">这是一份了解机会的邀请，不代表自动转投或面试、录用承诺。</p>`:''}<p style="margin-top:16px">感谢您投入的时间与认真准备。<br>招聘团队</p></div></div>`;}
 function editor(c,s){if(s.sent)return`<div class="panel"><div class="panel-title"><h2>本版沟通已模拟发送</h2><span class="badge">已记录</span></div><div class="notice">没有真实邮件发出。下方保留发送时的内容快照，可继续查看候选人如何选择。</div>${emailMarkup(c,s,s.sent)}<div class="actions">${btn('查看岗位复核','step','data-step="2"','secondary')}${btn('查看候选人视角 →','step','data-step="4"')}</div>${timeline(s)}</div>`;
 const valid=C.chosen(c,s),approved=s.approved===C.fingerprint(s),error=C.validate(c,s);return`<div class="panel"><div class="panel-title"><h2>这封沟通，由你决定</h2><span class="eyebrow">03 / HR APPROVAL</span></div><p class="subtext">反馈与岗位邀请分别选择。修改内容后，需要重新确认。</p><div class="editor-layout" style="margin-top:19px"><div><label class="checkrow"><input type="checkbox" checked disabled>告知原岗位结果（固定包含）</label><label class="checkrow"><input id="includeFeedback" type="checkbox" ${s.includeFeedback?'checked':''}>附上一句话面试反馈</label><label class="label" for="feedback">对外反馈草稿 · 可编辑</label><textarea id="feedback" ${!s.includeFeedback?'disabled':''}>${esc(s.feedback)}</textarea><p class="mini-note">仅沟通已确认的具体观察，不转发内部面评全文，不添加人格或职业诊断。</p><label class="checkrow"><input id="includeJobs" type="checkbox" ${s.includeJobs?'checked':''} ${!valid.length?'disabled':''}>附上已选岗位的了解邀请</label><div class="notice">${valid.length?`已选 ${valid.length} 个岗位：${valid.map(j=>esc(j.name)).join('、')}。`:'没有有效的已选岗位，可仅发送结果与反馈。'}</div><div class="approval ${approved?'ok':''}" id="approvalStatus">${approved?'✓ 已确认当前版本，可以模拟发送':'待 HR 确认 · 系统不会自行发送'}</div><div class="actions-right" style="margin-top:15px">${btn('确认本版内容','approve',error?'disabled':'','secondary')}${btn('模拟发送','send',!approved||error?'disabled':'')}</div><p class="mini-note" id="validationMessage">${esc(error||'所有操作仅在此演示中生效，没有真实邮件发送。')}</p></div><div><div class="label" style="margin-top:0">候选人将看到的内容</div><div id="emailPreview">${emailMarkup(c,s)}</div></div></div><div class="actions">${btn('← 返回岗位复核','step','data-step="2"','secondary')}</div></div>`;}
 function candidate(c,s){if(!s.sent)return`<div class="panel"><div class="empty"><b>尚未形成可查看的沟通</b><p>先由 HR 确认并模拟发送，再查看候选人收到的内容。</p><div style="margin-top:16px">${btn('前往沟通审核','step','data-step="3"')}</div></div></div>`;
 const declined=s.response==='decline',job=s.sent.jobs.find(j=>j.id===s.response);return`<div class="candidate-view"><div class="panel-title"><h2>候选人视角</h2><span class="badge demo">模拟收件箱</span></div>${emailMarkup(c,s,s.sent)}<div class="panel" style="margin-top:16px"><h3>下一步，由候选人选择</h3>${!s.sent.jobs.length?'<p class="subtext">本次未附岗位邀请，不创建转推流程，也不自动加入长期人才库。</p>':!s.response?`<p class="subtext">仅表示愿意进一步了解，不等于已获得面试资格。</p><div class="response-box"><label for="candidateJob" class="label">我愿意了解</label><select id="candidateJob">${s.sent.jobs.map(j=>`<option value="${j.id}">${esc(j.name)} · ${esc(j.city)}</option>`).join('')}</select><div class="actions-right">${btn('愿意进一步了解','accept')}${btn('暂不考虑其他机会','decline','','secondary')}</div></div>`:declined?'<div class="outcome">候选人选择暂不考虑。本次转推已结束，不再继续岗位邀请。</div>':`<div class="outcome">已表达对「${esc(job?.name)}」的了解意愿，等待目标岗位负责人确认。</div><div class="receiver"><div class="eyebrow">演示角色 · 目标岗位负责人</div><p class="subtext">接收人：${esc(job?.owner)}。此处仅演示交接，不替代后续面试。</p>${s.received?`<div class="outcome">${s.received==='yes'?'已接收，转入原有招聘流程。':'暂不接收，HR 后续沟通；不自动推荐更多岗位。'}</div>`:`<div class="actions-right">${btn('接收进一步评估','receive','data-value="yes"')}${btn('暂不接收','receive','data-value="no"','secondary')}</div>`}</div>`}${timeline(s)}</div></div>`;}
 function timeline(s){return s.events.length?`<div class="timeline"><div class="label">演示操作记录</div>${s.events.map(e=>`<div class="event"><small>${new Date(e.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</small>${esc(e.text)}</div>`).join('')}</div>`:'';}
 function invalidate(s){s.approved=null;}
 document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t||t.disabled)return;const c=getCase(),s=getState();switch(t.dataset.action){case'case':current=t.dataset.id;render();break;case'step':{const n=Number(t.dataset.step);if(n>1&&!s.analyzed)return;s.step=n;render();break;}case'analyze':if(s.verdict!=='不推进'||s.sent)return;s.analyzed=true;s.step=2;s.selected=C.jobs(c,s).filter(j=>j.eligible).map(j=>j.id);s.includeJobs=s.selected.length>0;invalidate(s);event('面评已确认，载入本案例预置岗位建议');render();break;case'approve':{const err=C.approve(c,s);if(err){toast(err);return;}event('HR 确认当前沟通内容与发送范围');render();toast('当前版本已确认，修改后将需要重新确认');break;}case'send':{const err=C.send(c,s);if(err){toast(err);return;}event('HR 完成模拟发送：'+(s.sent.jobs.length?'含岗位邀请':'不含岗位邀请'));render();toast('模拟发送已记录，没有真实邮件发出');break;}case'accept':{const id=document.getElementById('candidateJob')?.value;const err=C.respond(s,id);if(err){toast(err);return;}event('候选人愿意了解 '+id+'，等待接收');render();break;}case'decline':{const err=C.respond(s,'decline');if(err){toast(err);return;}event('候选人暂不考虑，本次转推结束');render();break;}case'receive':if(s.response&&s.response!=='decline'&&!s.received){s.received=t.dataset.value;event(s.received==='yes'?'目标岗位负责人接收，后续沿用原流程':'目标岗位暂不接收，交由 HR 沟通');render();}break;case'reset':records[current]=C.fresh(c);render();toast('当前样例已重置');break;case'export':{const blob=new Blob([JSON.stringify({demo:'Second Look',simulation:true,modelCalled:false,exportedAt:new Date().toISOString(),current,records},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='second-look-demo-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已导出演示操作记录，不含真实候选人数据');break;}}});
 document.addEventListener('change',e=>{const c=getCase(),s=getState(),el=e.target;if(s.sent)return;if(el.id==='verdict'||el.id==='intent'){s[el.id]=el.value;s.analyzed=false;s.selected=[];s.includeJobs=false;invalidate(s);render();}else if(el.id==='scenario'){s.scenario=el.value;s.selected=C.jobs(c,s).filter(j=>j.eligible).map(j=>j.id);s.includeJobs=s.selected.length>0;invalidate(s);event('切换验证场景：'+el.options[el.selectedIndex].text);render();}else if(el.id==='supply'){s.supply=el.checked;render();}else if(el.dataset.job){s.selected=s.selected.filter(id=>id!==el.dataset.job);if(el.checked)s.selected.push(el.dataset.job);if(!C.chosen(c,s).length)s.includeJobs=false;invalidate(s);render();}else if(el.id==='includeFeedback'||el.id==='includeJobs'){s[el.id]=el.checked;invalidate(s);render();}});
 document.addEventListener('input',e=>{if(e.target.id!=='feedback')return;const c=getCase(),s=getState();if(s.sent)return;s.feedback=e.target.value;invalidate(s);persist();document.getElementById('emailPreview').innerHTML=emailMarkup(c,s);const a=document.getElementById('approvalStatus');a.className='approval';a.textContent='内容已修改 · 请重新确认当前版本';const sendButton=document.querySelector('[data-action="send"]'),approveButton=document.querySelector('[data-action="approve"]');if(sendButton)sendButton.disabled=true;if(approveButton)approveButton.disabled=!!C.validate(c,s);document.getElementById('validationMessage').textContent=C.validate(c,s)||'所有操作仅在此演示中生效，没有真实邮件发送。';});
 render();
})();
